-- =============================================================================================
-- Hand-written below this line: integrity rules for charge types, recurring charges and
-- invoices; the issue check that ties an invoice to its posted journal entry; immutability of
-- issued invoices; row-level security and grants.
-- See docs/architecture/DATA_MODEL.md section 6 (Billing).
-- =============================================================================================

-- ---------------------------------------------------------------------------------------------
-- charge_types: book to an INCOME account of the same property (composite key + trigger).
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "charge_types" ADD CONSTRAINT "charge_types_code_format"
  CHECK ("code" ~ '^[A-Z0-9][A-Z0-9-]{1,19}$');
ALTER TABLE "charge_types" ADD CONSTRAINT "charge_types_name_trimmed"
  CHECK ("name" = btrim("name") AND length("name") BETWEEN 1 AND 120);
ALTER TABLE "charge_types" ADD CONSTRAINT "charge_types_archive_consistent"
  CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL));

CREATE FUNCTION app_charge_type_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW."organisation_id", NEW."property_id", NEW."code", NEW."created_at")
     IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."code", OLD."created_at") THEN
    RAISE EXCEPTION 'charge type % cannot move or change its code', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM "ledger_accounts" WHERE "id" = NEW."income_account_id" AND "type" = 'INCOME'
  ) THEN
    RAISE EXCEPTION 'a charge type books to an income account' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "charge_types_guard"
  BEFORE INSERT OR UPDATE ON "charge_types"
  FOR EACH ROW EXECUTE FUNCTION app_charge_type_guard();

-- ---------------------------------------------------------------------------------------------
-- recurring_charges: whole months; one charge per unit (or property-wide) and charge type at a
-- time; only the end month ever changes.
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "recurring_charges" ADD CONSTRAINT "recurring_charges_amount_positive"
  CHECK ("amount_minor" > 0);
ALTER TABLE "recurring_charges" ADD CONSTRAINT "recurring_charges_months"
  CHECK (extract(day FROM "start_month") = 1
         AND ("end_month" IS NULL OR (extract(day FROM "end_month") = 1 AND "end_month" >= "start_month")));
ALTER TABLE "recurring_charges" ADD CONSTRAINT "recurring_charges_no_overlap"
  EXCLUDE USING gist (
    "property_id" WITH =,
    "charge_type_id" WITH =,
    (coalesce("unit_id", '00000000-0000-0000-0000-000000000000'::uuid)) WITH =,
    daterange("start_month", "end_month", '[]') WITH &&
  );

CREATE FUNCTION app_recurring_charge_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF (NEW."organisation_id", NEW."property_id", NEW."unit_id", NEW."charge_type_id", NEW."basis",
      NEW."amount_minor", NEW."start_month", NEW."created_by_user_id", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."unit_id", OLD."charge_type_id", OLD."basis",
      OLD."amount_minor", OLD."start_month", OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'recurring charge % can only change its end month; end it and add a new one', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "recurring_charges_guard"
  BEFORE UPDATE ON "recurring_charges"
  FOR EACH ROW EXECUTE FUNCTION app_recurring_charge_guard();

-- ---------------------------------------------------------------------------------------------
-- invoices
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_currency_format"
  CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_bill_to_consistent"
  CHECK (("bill_to" = 'TENANTS') = ("tenancy_id" IS NOT NULL));
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_dates"
  CHECK (("billing_month" IS NULL OR extract(day FROM "billing_month") = 1)
         AND "due_date" >= "billing_date"
         AND ("issue_date" IS NULL OR "due_date" >= "issue_date"));
-- Issued invoices carry their number, issue date, posting time and journal entry; drafts none.
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_issue_consistent"
  CHECK (("status" = 'ISSUED') = ("invoice_number" IS NOT NULL)
         AND ("status" = 'ISSUED') = ("issued_at" IS NOT NULL)
         AND ("status" = 'ISSUED') = ("issue_date" IS NOT NULL)
         AND ("status" = 'ISSUED') = ("journal_entry_id" IS NOT NULL)
         AND ("issued_by_user_id" IS NULL OR "status" = 'ISSUED')
         AND ("total_minor" >= 0)
         AND ("status" = 'DRAFT' OR "total_minor" > 0));

CREATE FUNCTION app_invoice_insert_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."status" <> 'DRAFT' THEN
    RAISE EXCEPTION 'invoices are created as drafts and then issued' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."tenancy_id" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "tenancies" WHERE "id" = NEW."tenancy_id" AND "unit_id" = NEW."unit_id"
  ) THEN
    RAISE EXCEPTION 'the tenancy billed is not a tenancy of this unit' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "invoices_insert_check"
  BEFORE INSERT ON "invoices"
  FOR EACH ROW EXECUTE FUNCTION app_invoice_insert_check();

-- Issuing (DRAFT -> ISSUED) checks that the lines add up to the total, someone is billed, and
-- the journal entry is a posted INVOICE entry of the issue date that debits exactly the total to
-- the property's receivables for this unit, in the invoice's currency. It then numbers the
-- invoice (advisory lock: no gaps, no duplicates) and stamps issued_at. Issued invoices never
-- change; corrections are credit notes (Phase 6 Part 4).
CREATE FUNCTION app_invoice_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  line_total numeric;
  line_count integer;
  entry record;
  receivable numeric;
BEGIN
  IF OLD."status" = 'ISSUED' THEN
    RAISE EXCEPTION 'invoice % is issued and cannot change', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."unit_id", NEW."bill_to", NEW."tenancy_id",
      NEW."billing_month", NEW."billing_date", NEW."currency", NEW."created_by_user_id", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."unit_id", OLD."bill_to", OLD."tenancy_id",
      OLD."billing_month", OLD."billing_date", OLD."currency", OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'invoice % cannot change its unit, party, billing date or currency', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" = 'DRAFT' THEN
    RETURN NEW;
  END IF;

  SELECT count(*), coalesce(sum("amount_minor"), 0) INTO line_count, line_total
    FROM "invoice_lines" WHERE "invoice_id" = NEW."id";
  IF line_count = 0 OR line_total <> NEW."total_minor" THEN
    RAISE EXCEPTION 'invoice % lines (%) do not add up to its total (%)', OLD."id", line_total, NEW."total_minor"
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "invoice_recipients" WHERE "invoice_id" = NEW."id") THEN
    RAISE EXCEPTION 'invoice % is not addressed to anyone', OLD."id" USING ERRCODE = 'check_violation';
  END IF;

  SELECT "status", "source", "entry_date", "currency" INTO entry
    FROM "journal_entries" WHERE "id" = NEW."journal_entry_id";
  IF entry."status" IS DISTINCT FROM 'POSTED' OR entry."source" <> 'INVOICE'
     OR entry."entry_date" <> NEW."issue_date" OR entry."currency" <> NEW."currency" THEN
    RAISE EXCEPTION 'invoice % needs a posted invoice entry of its issue date', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT coalesce(sum(l."debit_minor") - sum(l."credit_minor"), 0) INTO receivable
    FROM "journal_lines" l JOIN "ledger_accounts" a ON a."id" = l."account_id"
   WHERE l."entry_id" = NEW."journal_entry_id" AND a."system_key" = 'RECEIVABLES'
     AND l."unit_id" = NEW."unit_id";
  IF receivable <> NEW."total_minor" THEN
    RAISE EXCEPTION 'invoice % entry must debit its total to the unit''s receivables', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.invoices:' || NEW."property_id"::text, 0));
  SELECT coalesce(max("invoice_number"), 0) + 1 INTO NEW."invoice_number"
    FROM "invoices" WHERE "property_id" = NEW."property_id";
  NEW."issued_at" := now();
  RETURN NEW;
END
$$;

CREATE TRIGGER "invoices_guard"
  BEFORE UPDATE ON "invoices"
  FOR EACH ROW EXECUTE FUNCTION app_invoice_guard();

CREATE FUNCTION app_invoice_delete_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."status" <> 'DRAFT' THEN
    RAISE EXCEPTION 'invoice % is issued and cannot be deleted', OLD."id"
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN OLD;
END
$$;

CREATE TRIGGER "invoices_delete_check"
  BEFORE DELETE ON "invoices"
  FOR EACH ROW EXECUTE FUNCTION app_invoice_delete_check();

-- ---------------------------------------------------------------------------------------------
-- invoice_lines and invoice_recipients: change only while the invoice is a draft (the invoice
-- row is share-locked, so a change and the issue are serialised).
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "invoice_lines" ADD CONSTRAINT "invoice_lines_amount_positive"
  CHECK ("amount_minor" > 0);
ALTER TABLE "invoice_lines" ADD CONSTRAINT "invoice_lines_line_number"
  CHECK ("line_number" >= 1);
ALTER TABLE "invoice_lines" ADD CONSTRAINT "invoice_lines_description_trimmed"
  CHECK ("description" = btrim("description") AND length("description") BETWEEN 1 AND 300);
-- A recurring line names its charge, unit and month together (the unique key against double
-- billing); the composite key ties the unit and month to the invoice's own.
ALTER TABLE "invoice_lines" ADD CONSTRAINT "invoice_lines_recurring_consistent"
  CHECK (("recurring_charge_id" IS NULL) = ("unit_id" IS NULL)
         AND ("recurring_charge_id" IS NULL) = ("billing_month" IS NULL));

ALTER TABLE "invoice_recipients" ADD CONSTRAINT "invoice_recipients_share"
  CHECK (("share_numerator" IS NULL) = ("share_denominator" IS NULL)
         AND ("share_numerator" IS NULL
              OR ("share_numerator" > 0 AND "share_denominator" > 0 AND "share_numerator" <= "share_denominator")));

CREATE FUNCTION app_invoice_child_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  invoice_status "InvoiceStatus";
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    SELECT "status" INTO invoice_status FROM "invoices" WHERE "id" = OLD."invoice_id" FOR SHARE;
    IF invoice_status IS DISTINCT FROM 'DRAFT' THEN
      RAISE EXCEPTION 'invoice % is issued and cannot change', OLD."invoice_id"
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    SELECT "status" INTO invoice_status FROM "invoices" WHERE "id" = NEW."invoice_id" FOR SHARE;
    IF invoice_status IS DISTINCT FROM 'DRAFT' THEN
      RAISE EXCEPTION 'invoice % is issued and cannot change', NEW."invoice_id"
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
  END IF;
  RETURN OLD;
END
$$;

CREATE TRIGGER "invoice_lines_guard"
  BEFORE INSERT OR UPDATE OR DELETE ON "invoice_lines"
  FOR EACH ROW EXECUTE FUNCTION app_invoice_child_guard();

CREATE TRIGGER "invoice_recipients_guard"
  BEFORE INSERT OR UPDATE OR DELETE ON "invoice_recipients"
  FOR EACH ROW EXECUTE FUNCTION app_invoice_child_guard();

-- A recurring line bills its recurring charge's own type, for a unit it applies to.
CREATE FUNCTION app_invoice_line_recurring_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."recurring_charge_id" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "recurring_charges"
     WHERE "id" = NEW."recurring_charge_id" AND "charge_type_id" = NEW."charge_type_id"
       AND ("unit_id" IS NULL OR "unit_id" = NEW."unit_id")
  ) THEN
    RAISE EXCEPTION 'the line does not match its recurring charge' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "invoice_lines_recurring_check"
  BEFORE INSERT OR UPDATE ON "invoice_lines"
  FOR EACH ROW EXECUTE FUNCTION app_invoice_line_recurring_check();

CREATE TRIGGER "invoices_no_truncate"
  BEFORE TRUNCATE ON "invoices"
  FOR EACH STATEMENT EXECUTE FUNCTION app_reject_ledger_truncate();

CREATE TRIGGER "invoice_lines_no_truncate"
  BEFORE TRUNCATE ON "invoice_lines"
  FOR EACH STATEMENT EXECUTE FUNCTION app_reject_ledger_truncate();

CREATE TRIGGER "invoice_recipients_no_truncate"
  BEFORE TRUNCATE ON "invoice_recipients"
  FOR EACH STATEMENT EXECUTE FUNCTION app_reject_ledger_truncate();

-- ---------------------------------------------------------------------------------------------
-- Row-level security: tenant context only (MULTI_TENANCY section 3.3).
-- ---------------------------------------------------------------------------------------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['charge_types', 'recurring_charges', 'invoices', 'invoice_lines', 'invoice_recipients'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['invoices', 'invoice_lines', 'invoice_recipients'] LOOP
    EXECUTE format('CREATE POLICY %I ON %I FOR DELETE USING (organisation_id = app_current_organisation_id())', t || '_delete', t);
  END LOOP;
END
$$;

-- ---------------------------------------------------------------------------------------------
-- Least privilege: charge types and recurring charges are never deleted; invoice rows only
-- while drafts (enforced by the triggers above).
-- ---------------------------------------------------------------------------------------------
REVOKE ALL ON "charge_types", "recurring_charges", "invoices", "invoice_lines", "invoice_recipients" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "charge_types", "recurring_charges" TO veyra_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON "invoices", "invoice_lines", "invoice_recipients" TO veyra_app;
